"""Git, etapas 4 y 5: Git avanzado y flujos de trabajo profesionales."""
from ..generador import K

E4 = [
K("git rebase", d="orden que mueve tus commits encima de otra rama", u="tener un historial lineal sin commits de merge",
  mas="git rebase main toma los commits de tu rama y los vuelve a aplicar sobre la punta de main. El historial queda en línea recta. Nunca hagas rebase de commits que ya compartiste con otros, porque cambia sus identificadores.",
  k=["git rebase reaplica tus commits sobre otra rama.", "Rebase deja el historial en línea recta.", "No se hace rebase de commits ya compartidos."],
  sit="Tu rama se quedó atrás de main y quieres poner tus commits encima de lo último sin crear un commit de merge. ¿Qué orden usas?",
  cod="""git switch mi-rama
git rebase main""", h="pone los commits de mi-rama encima de main",
  pr=("La orden que reaplica tus commits sobre otra rama es git ___. (6 letras)", "rebase"),
  pr2=("Si hay conflictos, después de arreglarlos se sigue con git rebase --___. (8 letras)", "continue"),
  ec="hacer rebase de una rama que tus compañeros ya descargaron", out="Successfully rebased and updated refs/heads/mi-rama."),
K("Rebase interactivo", d="rebase que te deja editar, unir o borrar commits", u="limpiar tus commits antes de abrir un pull request",
  mas="git rebase -i HEAD~3 abre una lista de los últimos 3 commits. Cambias pick por squash para unirlos, reword para cambiar el mensaje o drop para quitarlo. Así entregas un historial claro.",
  k=["git rebase -i permite editar commits anteriores.", "squash une un commit con el anterior.", "reword cambia solo el mensaje de un commit."],
  sit="Hiciste cinco commits llamados «arreglo», «arreglo 2»… y quieres dejarlos como uno solo antes del pull request. ¿Qué usas?",
  cod="""git rebase -i HEAD~3
# pick a1b2c3 Agrega formulario
# squash d4e5f6 arreglo
# squash 0789ab arreglo 2""", h="une los dos últimos arreglos con el commit del formulario",
  pr=("En el rebase interactivo, la palabra que une un commit con el anterior es ___. (6 letras)", "squash"),
  pr2=("La palabra que cambia solo el mensaje de un commit es ___. (6 letras)", "reword"),
  ec="borrar líneas por error en la lista y perder commits", out="[detached HEAD 9f8e7d6] Agrega formulario"),
K("git cherry-pick", d="orden que copia un commit concreto a tu rama actual", u="traer un arreglo puntual sin unir toda la otra rama",
  mas="git cherry-pick a1b2c3 aplica ese commit en tu rama como uno nuevo. Sirve para llevar un arreglo urgente de develop a main. Si hay conflicto, lo resuelves y sigues con git cherry-pick --continue.",
  k=["git cherry-pick copia un commit a la rama actual.", "Cherry-pick crea un commit nuevo con los mismos cambios.", "Se identifica el commit por su hash."],
  sit="En la rama develop hay un commit que arregla un error grave y lo necesitas ya en main, sin lo demás. ¿Qué orden usas?",
  cod="""git switch main
git cherry-pick a1b2c3""", h="copia el commit a1b2c3 a la rama main",
  pr=("La orden que copia un commit concreto es git cherry-___. (4 letras)", "pick"),
  pr2=("Para elegir el commit se usa su ___. (4 letras)", "hash"),
  ec="copiar muchos commits uno por uno en lugar de hacer merge", out="[main 3c4d5e6] Corrige el cálculo del IVA\n 1 file changed, 1 insertion(+), 1 deletion(-)"),
K("git reflog", d="registro de todos los lugares donde estuvo HEAD", u="recuperar commits que creías perdidos",
  mas="Aunque borres una rama o hagas reset --hard, Git guarda unos días el historial de HEAD. git reflog lo muestra y con git switch -c rescate HEAD@{2} recuperas ese punto.",
  k=["git reflog muestra el historial de HEAD.", "Con reflog se recuperan commits tras un reset.", "HEAD@{1} es la posición anterior de HEAD."],
  sit="Hiciste git reset --hard por error y desaparecieron tus últimos commits. ¿Qué orden te muestra dónde estaban?",
  cod="""git reflog
git switch -c rescate HEAD@{1}""", h="muestra el historial de HEAD y recupera un punto anterior",
  pr=("La orden que muestra por dónde pasó HEAD es git ___. (6 letras)", "reflog"),
  pr2=("HEAD@{0} es la posición ___ de HEAD. (6 letras)", "actual"),
  ec="creer que reset --hard borró todo para siempre", out="9f8e7d6 HEAD@{0}: reset: moving to HEAD~2\n3c4d5e6 HEAD@{1}: commit: Agrega login"),
K("git bisect", d="búsqueda binaria entre commits para encontrar cuál trajo un error", u="encontrar rápido el commit que rompió algo",
  mas="git bisect start, luego git bisect bad (el actual falla) y git bisect good v1.0 (ahí funcionaba). Git te lleva a commits intermedios y respondes good o bad hasta encontrar el culpable. Termina con git bisect reset.",
  k=["git bisect hace una búsqueda binaria en el historial.", "git bisect bad marca un commit con el error.", "git bisect reset termina la búsqueda."],
  sit="Algo funcionaba hace 200 commits y ahora no, y no sabes cuál lo rompió. ¿Qué herramienta de Git lo encuentra en pocos pasos?",
  cod="""git bisect start
git bisect bad
git bisect good v1.0""", h="empieza a buscar el commit que trajo el error",
  pr=("La herramienta de Git que busca el commit culpable es git ___. (6 letras)", "bisect"),
  pr2=("Para marcar que un commit funciona bien se escribe git bisect ___. (4 letras)", "good"),
  ec="olvidar git bisect reset y quedarse en un commit viejo", out="Bisecting: 99 revisions left to test after this (roughly 7 steps)"),
K("git blame", d="orden que muestra quién cambió cada línea y en qué commit", u="entender por qué existe una línea antes de cambiarla",
  mas="git blame archivo.js muestra, línea por línea, el commit, el autor y la fecha del último cambio. VS Code lo muestra con GitLens. No es para culpar: sirve para encontrar el contexto de un cambio.",
  k=["git blame muestra el autor de cada línea.", "git blame indica el commit del último cambio.", "git blame -L limita el resultado a unas líneas."],
  sit="Una línea rara de configuración parece innecesaria y quieres saber en qué commit y por qué se agregó. ¿Qué orden usas?",
  cod="""git blame -L 10,12 app.js""", h="muestra quién cambió las líneas 10 a 12",
  pr=("La orden que muestra quién cambió cada línea es git ___. (5 letras)", "blame"),
  pr2=("La opción de blame que limita las líneas es -___. (1 letra)", "L"),
  ec="usar blame para culpar a alguien en lugar de entender el cambio", out="3c4d5e6 (Ana 2026-10-02 10)   const PUERTO = 3000;"),
K("Hooks de Git", d="scripts que Git ejecuta solo antes o después de ciertas acciones", u="revisar el código o los mensajes antes de cada commit",
  mas="Viven en .git/hooks: pre-commit corre antes del commit (por ejemplo, el linter), commit-msg revisa el mensaje y pre-push corre las pruebas. Herramientas como Husky los comparten con el equipo.",
  k=["pre-commit se ejecuta antes de cada commit.", "Los hooks viven en la carpeta .git/hooks.", "Husky comparte hooks entre el equipo."],
  sit="Quieres que el formateador revise el código automáticamente justo antes de cada commit. ¿Qué mecanismo de Git usas?",
  cod="""#!/bin/sh
# .git/hooks/pre-commit
npm run lint || exit 1""", h="impide el commit si el linter falla",
  pr=("El hook que se ejecuta antes de cada commit es pre-___. (6 letras)", "commit"),
  pr2=("La herramienta que comparte hooks en proyectos de Node es ___. (5 letras)", "husky"),
  ec="creer que los hooks de .git/hooks se suben al repositorio", out="✖ 2 problemas (1 error, 1 advertencia)"),
K("Submódulos", d="repositorios de Git dentro de otro repositorio", u="incluir una librería externa sin copiar su código",
  mas="git submodule add URL carpeta agrega otro repositorio en una versión fija. Quien clona usa git clone --recurse-submodules o git submodule update --init. Para cosas simples suele ser mejor un gestor de paquetes.",
  k=["Un submódulo es un repositorio dentro de otro.", "git submodule add agrega un submódulo.", "--recurse-submodules clona también los submódulos."],
  sit="Tu proyecto usa un tema de otro repositorio y quieres tenerlo dentro sin copiarlo a mano. ¿Qué función de Git usas?",
  cod="""git submodule add https://github.com/ana/tema.git tema
git submodule status""", h="agrega un submódulo y muestra su estado",
  pr=("Un repositorio dentro de otro se llama ___. (9 letras)", "submodulo", "submódulo"),
  pr2=("Para clonar con submódulos se usa --recurse-___. (10 letras)", "submodules"),
  ec="clonar sin --recurse-submodules y ver la carpeta vacía", out=" 1a2b3c4 tema (heads/main)"),
]

E5 = [
K("Git Flow", d="modelo de ramas con main, develop, feature, release y hotfix", u="organizar equipos con versiones planificadas",
  mas="main tiene solo versiones publicadas y develop lo que viene. Cada función nace en feature/…, se prepara una versión en release/… y los arreglos urgentes salen de hotfix/…. Es ordenado pero pesado para proyectos pequeños.",
  k=["En Git Flow, main tiene solo versiones publicadas.", "Las funciones nuevas van en ramas feature.", "Los arreglos urgentes van en ramas hotfix."],
  sit="Tu equipo publica una versión cada mes y necesita separar lo publicado de lo que se está desarrollando. ¿Qué modelo de ramas usa?",
  cod="""git switch -c feature/carrito develop
git switch -c hotfix/pago main""", h="crea una rama de función y una de arreglo urgente",
  pr=("En Git Flow, los arreglos urgentes salen de ramas ___. (6 letras)", "hotfix"),
  pr2=("La rama donde se integra lo que viene es ___. (7 letras)", "develop"),
  ec="usar Git Flow completo en un proyecto personal pequeño", out="Switched to a new branch 'hotfix/pago'"),
K("Trunk-based development", d="flujo donde todos integran cambios pequeños en main muy seguido", u="publicar rápido y evitar ramas que viven semanas",
  mas="Las ramas duran horas o pocos días y se unen a main (el tronco) con pruebas automáticas. Lo que no está terminado se esconde con banderas de funciones (feature flags). Lo usan Google y muchos equipos con despliegue continuo.",
  k=["En trunk-based las ramas duran muy poco.", "Todos integran en la rama principal.", "Las feature flags esconden lo que no está terminado."],
  sit="Tu equipo sufre conflictos enormes porque cada rama vive tres semanas. ¿Qué forma de trabajar lo evita?",
  cod="""git switch -c boton-pago
git commit -am "Agrega botón de pago (oculto)"
git push -u origin boton-pago""", h="una rama corta que pronto se une a main",
  pr=("En trunk-based, el tronco es la rama ___. (4 letras)", "main"),
  pr2=("Para esconder funciones sin terminar se usan feature ___. (5 letras)", "flags"),
  ec="dejar ramas abiertas semanas y llamarlo trunk-based", out="branch 'boton-pago' set up to track 'origin/boton-pago'."),
K("Conventional Commits", d="convención para escribir mensajes de commit con un tipo", u="que el historial se entienda y se generen versiones solas",
  mas="El mensaje empieza con un tipo: feat (función nueva), fix (arreglo), docs, refactor, test, chore. Por ejemplo: feat(login): agrega Google. Con ! o BREAKING CHANGE se avisa un cambio incompatible.",
  k=["feat indica una función nueva.", "fix indica un arreglo de error.", "BREAKING CHANGE avisa un cambio incompatible."],
  sit="Quieres que cualquiera sepa, solo con leer el historial, qué commits agregan funciones y cuáles arreglan errores. ¿Qué convención usas?",
  cod="""git commit -m "feat(carrito): agrega cupones"
git commit -m "fix(pago): corrige el redondeo\"""", h="dos commits con el formato convencional",
  pr=("El tipo de Conventional Commits para una función nueva es ___. (4 letras)", "feat"),
  pr2=("El tipo para un arreglo de error es ___. (3 letras)", "fix"),
  ec="escribir mensajes como «cambios» o «arreglos varios»", out="[main 4d5e6f7] fix(pago): corrige el redondeo"),
K("Versionado semántico", d="formato de versión MAYOR.MENOR.PARCHE", u="avisar con el número qué tan grande es un cambio",
  mas="En 2.4.1, el parche (1) sube con arreglos, la menor (4) con funciones compatibles y la mayor (2) con cambios que rompen. En package.json, ^2.4.1 acepta 2.x y ~2.4.1 solo 2.4.x. Las versiones se marcan con etiquetas como v2.4.1.",
  k=["La versión mayor sube con cambios incompatibles.", "La versión de parche sube con arreglos.", "Las versiones se marcan con etiquetas de Git."],
  sit="Arreglaste un error sin cambiar nada más en tu librería 1.3.0. ¿Qué número de versión publicas?",
  cod="""git tag -a v1.3.1 -m "Corrige el cálculo"
git push origin v1.3.1""", h="marca y publica la versión 1.3.1",
  pr=("Tras un arreglo, la versión 1.3.0 pasa a 1.3.___. (1 dígito)", "1"),
  pr2=("El número que sube con cambios incompatibles es la versión ___. (5 letras)", "mayor"),
  ec="subir solo el parche cuando se rompe la compatibilidad", out=""),
K("Revisión de código", d="práctica de leer y comentar el código de otra persona antes de unirlo", u="encontrar errores y compartir conocimiento en el equipo",
  mas="En un pull request se revisa que el código funcione, sea claro y tenga pruebas. Se comenta con respeto y con propuestas concretas. Pull requests pequeños se revisan mejor que uno gigante.",
  k=["La revisión de código se hace antes de unir los cambios.", "Los pull requests pequeños se revisan mejor.", "Los comentarios de revisión deben ser concretos."],
  sit="Antes de unir el trabajo de un compañero a main, quieres que otra persona lo lea y detecte problemas. ¿Qué práctica aplicas?",
  cod="""gh pr checkout 42
gh pr review 42 --approve -b "Funciona, gracias\"""", h="descarga un pull request y lo aprueba",
  pr=("Un pull request revisado y aceptado queda ___. (8 letras)", "aprobado"),
  pr2=("Conviene que los pull requests sean ___. (8 letras)", "pequeños", "pequenos"),
  ec="aprobar sin leer solo porque el autor tiene experiencia", out="✓ Approved pull request #42"),
K("Ramas protegidas", d="reglas que impiden cambiar una rama sin revisión", u="que nadie suba código directo a main por accidente",
  mas="En GitHub (Settings → Branches o Rulesets) puedes exigir pull request, aprobaciones y pruebas que pasen antes de unir a main. También se bloquea el push --force y el borrado de la rama.",
  k=["Una rama protegida exige pull request para cambiar.", "Las ramas protegidas pueden exigir pruebas aprobadas.", "Proteger una rama impide el push --force."],
  sit="Un compañero subió por error código roto directo a main. ¿Qué configuración lo evita la próxima vez?",
  cod="""git push origin main
# remote: error: GH006: Protected branch update failed""", h="un push directo a main bloqueado",
  pr=("Una rama con reglas que exigen revisión es una rama ___. (9 letras)", "protegida"),
  pr2=("Las ramas protegidas bloquean el push --___. (5 letras)", "force"),
  ec="darle a todos permiso de saltarse las reglas", out="remote: error: GH006: Protected branch update failed for refs/heads/main."),
K("Monorepo", d="un solo repositorio con varios proyectos o paquetes", u="compartir código entre frontend, backend y librerías",
  mas="En un monorepo, apps/web, apps/api y packages/ui viven juntos con un solo historial. Herramientas como npm workspaces, pnpm, Turborepo o Nx los organizan. La alternativa son varios repositorios (polyrepo).",
  k=["Un monorepo guarda varios proyectos en un repositorio.", "npm workspaces organiza paquetes en un monorepo.", "Polyrepo significa un repositorio por proyecto."],
  sit="Tu frontend y tu API comparten tipos y quieres cambiarlos en un solo pull request. ¿Qué organización de repositorio usas?",
  cod="""{
  "name": "mi-empresa",
  "workspaces": ["apps/*", "packages/*"]
}""", h="package.json raíz de un monorepo con workspaces",
  pr=("Un solo repositorio con varios proyectos se llama ___. (8 letras)", "monorepo"),
  pr2=("La alternativa de un repositorio por proyecto se llama ___. (8 letras)", "polyrepo"),
  ec="mezclar proyectos sin estructura y llamarlo monorepo", out=""),
K("git worktree", d="orden que abre otra rama en una carpeta aparte del mismo repositorio", u="trabajar en dos ramas a la vez sin stash ni clonar de nuevo",
  mas="git worktree add ../arreglo hotfix crea la carpeta ../arreglo con la rama hotfix, compartiendo el mismo .git. Puedes tener ambas abiertas en VS Code. Se quita con git worktree remove.",
  k=["git worktree abre otra rama en otra carpeta.", "Los worktrees comparten el mismo repositorio.", "git worktree remove quita una carpeta de trabajo."],
  sit="Estás a mitad de una función y te piden revisar urgente otra rama sin perder lo que tienes abierto. ¿Qué orden usas?",
  cod="""git worktree add ../revision feature/login
git worktree list""", h="abre feature/login en otra carpeta",
  pr=("La orden que abre otra rama en una carpeta aparte es git ___. (8 letras)", "worktree"),
  pr2=("Para ver las carpetas de trabajo se usa git worktree ___. (4 letras)", "list"),
  ec="borrar la carpeta a mano en lugar de usar git worktree remove", out="/home/ana/tienda    3c4d5e6 [main]\n/home/ana/revision  9f8e7d6 [feature/login]"),
]
